css:
/* Craft direction adapted from Unslop by Damir Sokolovsky, CC BY 4.0. */
.scope-filter select,.type-filter select{max-width:{{token:percentage-100}}}
.project-context{display:flex;align-items:flex-start;justify-content:space-between;gap:{{token:dimension-16px}};margin-bottom:{{token:dimension-16px}}}.project-context>div:first-child{flex:1;min-width:0}.project-context h1{font-size:{{token:dimension-24px}};line-height:{{token:number-1p35}}}.project-meta{font-size:{{token:dimension-12px}};color:var(--muted);margin-top:{{token:dimension-4px}}}.scope-filter{position:relative;flex:none;min-width:{{token:dimension-112px}};height:{{token:dimension-32px}}}.scope-filter label{display:none}.scope-filter select{position:absolute;inset:0;width:{{token:percentage-100}};height:{{token:percentage-100}};opacity:{{token:number-0}};cursor:pointer}.scope-filter:focus-within{outline:{{token:dimension-2px}} solid var(--accent);outline-offset:{{token:dimension-2px}}}.scope-label{display:flex;align-items:center;justify-content:space-between;gap:{{token:dimension-8px}};height:{{token:dimension-32px}};padding:{{token:dimension-4px}} {{token:dimension-8px}};border:{{token:dimension-1px}} solid var(--line);border-radius:{{token:dimension-4px}};font-size:{{token:dimension-12px}};color:var(--muted);pointer-events:none}.scope-label:after{content:"⌄"}
.preview-strip{display:grid;grid-template-columns:repeat(2,minmax(0,{{token:grid-track-1}}));gap:{{token:dimension-12px}};margin:0 0 {{token:dimension-24px}}}.preview-strip figure{margin:0;min-width:0}.preview-strip img{display:block;width:{{token:percentage-100}};height:{{local:previewImageHeight}};object-fit:contain;object-position:{{token:percentage-50}} 0;background:#fff;border:{{token:dimension-1px}} solid var(--line);border-radius:{{token:dimension-4px}}}.preview-strip figcaption{margin-top:{{token:dimension-8px}};font-size:{{token:dimension-12px}};color:var(--muted);line-height:{{token:number-1p4}}}
.next-action{margin:0 0 {{token:dimension-24px}};padding:0 0 {{token:dimension-24px}};border:0;border-bottom:{{token:dimension-1px}} solid var(--line);border-radius:0;background:none}.next-action .eyebrow{font-size:{{token:dimension-12px}};line-height:{{token:dimension-16px}};color:var(--muted);margin-bottom:{{token:dimension-8px}}}.next-line{display:flex;align-items:flex-start;gap:{{token:dimension-16px}}}.next-line h2{flex:1;min-width:0;font-size:{{token:dimension-20px}};line-height:{{token:number-1p4}}}.next-line button{flex:none}.next-action .next-description{font-size:{{token:dimension-13px}};line-height:{{token:dimension-20px}};color:var(--muted);margin-top:{{token:dimension-8px}}}.next-action .actions{margin-top:{{token:dimension-16px}}}
.list-heading{font-size:{{token:dimension-12px}};color:var(--muted);margin-bottom:{{token:dimension-8px}}}.task-row{margin:0}.task-hit{display:flex;align-items:center;text-align:left;width:{{token:percentage-100}};gap:{{token:dimension-12px}};min-height:{{token:dimension-64px}};padding:{{token:dimension-12px}} 0;border:0;border-bottom:{{token:dimension-1px}} solid var(--line);border-radius:0;background:transparent}.task-hit:not(:disabled):hover{background:var(--surface);border-color:var(--line)}.task-hit:disabled{background:transparent;opacity:{{token:number-1}};color:var(--muted)}.task-info{display:block;flex:1;min-width:0}.task-title{display:block;font-size:{{token:dimension-14px}};font-weight:{{token:number-500}};line-height:{{token:dimension-20px}}}.task-scope{display:block;font-size:{{token:dimension-12px}};color:var(--muted);margin-top:{{token:dimension-4px}}}.task-state{display:block;font-size:{{token:dimension-12px}};color:var(--muted);margin-top:{{token:dimension-4px}}}.task-state[data-status="failed"]{color:var(--danger)}.task-state[data-status="verified"]{color:var(--positive)}.task-arrow{font-size:{{token:dimension-16px}};color:var(--muted)}.document-mark{position:relative;display:block;width:{{token:dimension-28px}};height:{{token:dimension-36px}};flex:none;border:{{token:dimension-1px}} solid var(--line);border-radius:{{token:dimension-2px}};background:var(--surface)}.document-mark:after{content:"";position:absolute;left:{{token:dimension-6px}};right:{{token:dimension-6px}};top:{{token:dimension-10px}};height:{{token:dimension-1px}};background:var(--muted);box-shadow:0 {{token:dimension-5px}} 0 var(--muted),0 {{token:dimension-10px}} 0 var(--muted)}
.type-filter{display:flex;align-items:center;justify-content:flex-end;gap:{{token:dimension-8px}};margin-bottom:{{token:dimension-16px}};font-size:{{token:dimension-12px}};color:var(--muted)}
.recent-receipt{display:flex;gap:{{token:dimension-8px}};align-items:flex-start;margin:0 0 {{token:dimension-24px}};padding:0;color:var(--muted);font-size:{{token:dimension-12px}};line-height:{{token:dimension-20px}}}.receipt-mark{width:{{token:dimension-8px}};height:{{token:dimension-8px}};border:{{token:dimension-1px}} solid currentColor;flex:none;margin-top:{{token:dimension-6px}};border-radius:{{token:percentage-50}}}.receipt-mark[data-status="failed"]{border-radius:{{token:dimension-1px}};transform:rotate(45deg);color:var(--danger)}.receipt-copy{flex:1;min-width:0}.receipt-time{font-variant-numeric:tabular-nums;color:var(--muted);font-size:{{token:dimension-11px}};white-space:nowrap}
.history-row{position:relative;padding:0 0 {{token:dimension-24px}} {{token:dimension-24px}};border-left:{{token:dimension-1px}} solid var(--line);margin-left:{{token:dimension-4px}}}.history-row:before{content:"";position:absolute;left:{{token:dimension-neg4px}};top:{{token:dimension-4px}};width:{{token:dimension-7px}};height:{{token:dimension-7px}};border:{{token:dimension-1px}} solid var(--muted);border-radius:{{token:percentage-50}};background:var(--paper)}.history-row[data-status="failed"]:before{border-color:var(--danger);border-radius:0;transform:rotate(45deg)}.history-row[data-status="verified"]:before,.history-row[data-status="finished"]:before{background:var(--muted)}.history-meta{display:flex;justify-content:space-between;gap:{{token:dimension-8px}};color:var(--muted);font-size:{{token:dimension-11px}};line-height:{{token:dimension-16px}};margin-bottom:{{token:dimension-4px}}}.history-row h3{font-size:{{token:dimension-14px}};line-height:{{token:dimension-20px}}}.history-row p{font-size:{{token:dimension-12px}};color:var(--muted);line-height:{{token:dimension-20px}};margin-top:{{token:dimension-4px}}}.history-row button{margin-top:{{token:dimension-8px}}}.empty-state{padding:{{token:dimension-16px}} 0;color:var(--muted)}
@media(max-width:{{media:breakpoint-380px}}){.project-context{gap:{{token:dimension-8px}}}.project-context h1{font-size:{{token:dimension-20px}}}.scope-filter{max-width:{{token:dimension-120px}}}.preview-strip img{height:{{token:dimension-120px}}}.receipt-time{display:none}}
